import{_ as i,a0 as n,w as l,s as u,I as r,x as t,a1 as a,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux下如何過濾、分割以及合併 pcap 文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux下如何過濾、分割以及合併 pcap 文件 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux下如何過濾、分割以及合併 pcap 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux下如何過濾、分割以及合併 pcap 文件 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/How to filter, split or merge pcap files on Linux","title":"Linux下如何過濾、分割以及合併 pcap 文件","tag":"201501","desc":""},"relativePath":"201501/How to filter, split or merge pcap files on Linux.md","filePath":"[post].md"}'),s={name:"201501/How to filter, split or merge pcap files on Linux.md"};function m(f,p,c,g,x,w){const e=n("Link");return l(),u("div",null,[p[27]||(p[27]=r("h1",{id:"linux下如何過濾、分割以及合併-pcap-文件",tabindex:"-1"},[t("Linux下如何過濾、分割以及合併 pcap 文件 "),r("a",{class:"header-anchor",href:"#linux下如何過濾、分割以及合併-pcap-文件","aria-label":"Permalink to “Linux下如何過濾、分割以及合併 pcap 文件”"},"​")],-1)),r("p",null,[p[2]||(p[2]=t("如果你是一個測試",-1)),a(e,{href:"http://xmodulo.com/how-to-compile-and-install-snort-from-source-code-on-ubuntu.html"},{default:o(()=>[...p[0]||(p[0]=[t("入侵偵測系統",-1)])]),_:1}),p[3]||(p[3]=t("或一些網絡訪問控制策略的網絡管理員，那麼你經常需要抓取數據包並在離線狀態下分析這些文件。當需要保存捕獲的數據包時，我們一般會存儲為 libpcap 的數據包格式 pcap，這是一種被許多開源的嗅探工具以及捕包程序廣泛使用的格式。如果 pcap 文件被用於入侵測試或離線分析的話，那麼在將他們",-1)),a(e,{href:"http://xmodulo.com/how-to-capture-and-replay-network-traffic-on-linux.html"},{default:o(()=>[...p[1]||(p[1]=[t("注入",-1)])]),_:1}),p[4]||(p[4]=t("網絡之前通常要先對 pcap 文件進行一些操作。",-1))]),p[28]||(p[28]=d(`<p><img src="https://farm8.staticflickr.com/7570/15425147404_a69f416673_c.jpg" alt=""></p><p>在這篇文章中，我將介紹一些操作 pcap 文件的工具，以及如何使用它們 。</p><h3 id="editcap-與-mergecap" tabindex="-1">Editcap 與 Mergecap### <a class="header-anchor" href="#editcap-與-mergecap" aria-label="Permalink to “Editcap 與 Mergecap###”">​</a></h3><p>Wireshark，是最受歡迎的 GUI 嗅探工具，實際上它帶了一套非常有用的命令列工具集。其中包括 editcap 與 mergecap。editcap 是一個萬能的 pcap 編輯器，它可以過濾並且能以多種方式來分割 pcap 文件。mergecap 可以將多個 pcap 文件合併為一個。 這篇文章就是基於這些 Wireshark 命令列工具的。</p><p>如果你已經安裝過 Wireshark 了，那麼這些工具已經在你的系統中了。如果還沒裝的話，那麼我們接下來就安裝 Wireshark 命令列工具。 需要注意的是，在基於 Debian 的發行版上我們可以不用安裝 Wireshark GUI 而僅安裝命令列工具，但是在 Red Hat 及 基於它的發行版中則需要安裝整個 Wireshark 包。</p><p><strong>Debian, Ubuntu 或 Linux Mint</strong></p><pre><code>$ sudo apt-get install wireshark-common
</code></pre><p><strong>Fedora, CentOS 或 RHEL</strong></p><pre><code>$ sudo yum install wireshark
</code></pre><p>當安裝好工具後， 就可以開始使用 editca 與 mergecap 了。</p><h3 id="pcap-文件過濾" tabindex="-1">pcap 文件過濾### <a class="header-anchor" href="#pcap-文件過濾" aria-label="Permalink to “pcap 文件過濾###”">​</a></h3><p>通過 editcap， 我們能以很多不同的規則來過濾 pcap 文件中的內容，並且將過濾結果保存到新文件中。</p><p>首先，以“起止時間”來過濾 pcap 文件。 &quot; - A &lt; start-time &gt; 和 &quot; - B &lt; end-time &gt; 選項可以過濾出在這個時間段到達的數據包（如，從 2:30 ～ 2:35）。時間的格式為 “ YYYY-MM-DD HH:MM:SS&quot;。</p><pre><code>$ editcap -A &#39;2014-12-10 10:11:01&#39; -B &#39;2014-12-10 10:21:01&#39; input.pcap output.pcap 
</code></pre><p>也可以從某個文件中提取指定的 N 個包。下面的命令列從 input.pcap 文件中提取100個包（從 401 到 500）並將它們保存到 output.pcap 中：</p><pre><code>$ editcap input.pcap output.pcap 401-500
</code></pre><p>使用 &quot;-D &lt; dup-window &gt;&quot; （dup-window可以看成是對比的窗口大小，僅與此範圍內的包進行對比）選項可以提取出重複包。每個包都依次與它之前的 &lt; dup-window &gt; -1 個包對比長度與MD5值，如果有匹配的則丟棄。</p><pre><code>$ editcap -D 10 input.pcap output.pcap
</code></pre><blockquote><p>遍歷了 37568 個包, 在 10 窗口內重複的包僅有一個，並丟棄。</p></blockquote><p>也可以將 &lt; dup-window &gt; 定義成時間間隔。使用&quot;-w &lt; dup-time-window &gt;&quot;選項，對比&lt; dup-time-window &gt; 時間內到達的包。</p><pre><code>$ editcap -w 0.5 input.pcap output.pcap 
</code></pre><blockquote><p>檢索了 50000 個包, 以0.5s作為重複窗口，未找到重複包。</p></blockquote><p>###分割 pcap 文件###</p><p>當需要將一個大的 pcap 文件分割成多個小文件時，editcap 也能起很大的作用。</p><p>將一個 pcap 文件分割成數據包數目相同的多個文件</p><pre><code>$ editcap -c &lt;packets-per-file&gt; &lt;input-pcap-file&gt; &lt;output-prefix&gt; 
</code></pre><p>輸出的每個文件有相同的包數量，以 &lt; output-prefix &gt;-NNNN的形式命名。</p><p>以時間間隔分割 pcap 文件</p><pre><code>$ editcap -i &lt;seconds-per-file&gt; &lt;input-pcap-file&gt; &lt;output-prefix&gt; 
</code></pre><p>###合併 pcap 文件###</p><p>如果想要將多個文件合併成一個，用 mergecap 就很方便。</p><p>當合並多個文件時，mergecap 默認將內部的數據包以時間先後來排序。</p><pre><code>$ mergecap -w output.pcap input.pcap input2.pcap [input3.pcap . . .]
</code></pre><p>如果要忽略時間戳，僅僅想以命令列中的順序來合併文件，那麼使用 -a 選項即可。</p><p>例如，下列命令會將 input.pcap 文件的內容寫入到 output.pcap, 並且將 input2.pcap 的內容追加在後面。</p><pre><code>$ mergecap -a -w output.pcap input.pcap input2.pcap 
</code></pre><p>###總結###</p>`,37)),r("p",null,[p[9]||(p[9]=t("在這篇指導中，我演示了多個 editcap、 mergecap 操作 pcap 文件的例子。除此之外，還有其它的相關工具，如 ",-1)),a(e,{href:"https://www.wireshark.org/docs/man-pages/reordercap.html"},{default:o(()=>[...p[5]||(p[5]=[t("reordercap",-1)])]),_:1}),p[10]||(p[10]=t("用於將數據包重新排序，",-1)),a(e,{href:"https://www.wireshark.org/docs/man-pages/text2pcap.html"},{default:o(()=>[...p[6]||(p[6]=[t("text2pcap",-1)])]),_:1}),p[11]||(p[11]=t(" 用於將 pcap 文件轉換為文本格式， ",-1)),a(e,{href:"https://github.com/isginf/pcap-diff"},{default:o(()=>[...p[7]||(p[7]=[t("pcap-diff",-1)])]),_:1}),p[12]||(p[12]=t("用於比較 pcap 文件的異同，等等。當進行網絡入侵測試及解決網絡問題時，這些工具與",-1)),a(e,{href:"http://xmodulo.com/how-to-capture-and-replay-network-traffic-on-linux.html"},{default:o(()=>[...p[8]||(p[8]=[t("包注入工具",-1)])]),_:1}),p[13]||(p[13]=t("非常實用，所以最好了解他們。",-1))]),p[29]||(p[29]=r("p",null,"你是否使用過 pcap 工具？ 如果用過的話，你用它來做過什麼呢？",-1)),p[30]||(p[30]=r("hr",null,null,-1)),r("p",null,[p[15]||(p[15]=t("via: ",-1)),a(e,{href:"http://xmodulo.com/filter-split-merge-pcap-linux.html"},{default:o(()=>[...p[14]||(p[14]=[t("http://xmodulo.com/filter-split-merge-pcap-linux.html",-1)])]),_:1})]),r("p",null,[p[19]||(p[19]=t("作者：",-1)),a(e,{href:"http://xmodulo.com/author/nanni"},{default:o(()=>[...p[16]||(p[16]=[t("Dan Nanni",-1)])]),_:1}),p[20]||(p[20]=t(" 譯者：",-1)),a(e,{href:"https://github.com/SPccman"},{default:o(()=>[...p[17]||(p[17]=[t("SPccman",-1)])]),_:1}),p[21]||(p[21]=t(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:o(()=>[...p[18]||(p[18]=[t("wxy",-1)])]),_:1})]),r("p",null,[p[24]||(p[24]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...p[22]||(p[22]=[t("LCTT",-1)])]),_:1}),p[25]||(p[25]=t(" 原創翻譯，",-1)),a(e,{href:"http://linux.cn/"},{default:o(()=>[...p[23]||(p[23]=[t("Linux中國",-1)])]),_:1}),p[26]||(p[26]=t(" 榮譽推出",-1))])])}const b=i(s,[["render",m]]);export{T as __pageData,b as default};
